7: import { WorktrayContext } from "../../context/worktray-context";
8: import { config } from "../../services";
9: import locale from "../../services/locale";
10: import { WorktrayFilterOptions } from "../../types";
11: import { Patch } from "../../types/patch";
12: import { FilterBox, Option } from "./filter-box";
13: 
14: import "./styles.scss";
15: 
16: const { components } = locale;
17: 
18: enum FilterType {
19:   PROCESS_NAMES = "processNames",
20:   PATCH = "patch",
21: }
22: 
23: const sortAlphaNum = ({ value: a }, { value: b }) => {
24:   const reA = /[^a-zA-Z]/g;
25:   const reN = /[^0-9]/g;
26:   const aA = a.replace(reA, "");
27:   const bA = b.replace(reA, "");
28:   if (aA === bA) {
29:     const aN = parseInt(a.replace(reN, ""), 10);
30:     const bN = parseInt(b.replace(reN, ""), 10);
31:     if (aN === bN) {
32:       return 0;
33:     }
34:     return aN > bN ? 1 : -1;
35:   }
36:   return aA > bA ? 1 : -1;
37: };
